use std::fmt;

#[derive(Debug)]
pub enum CliError {
    UnrecognizedSubcommand {
        command: String,
        parent_usage: String,
    },
    UnexpectedArgument {
        arg: String,
        usage: String,
        tip_as_value: bool,
    },
    MissingRequired {
        missing: Vec<String>,
        usage: String,
    },
    ValueRequired {
        arg: String,
    },
    InvalidValue {
        arg: String,
        value: String,
        reason: String,
    },
    RequiresSubcommand {
        bin: String,
        subcommands: Vec<&'static str>,
        usage: String,
    },
    Generic(String),
}

impl CliError {
    pub fn exit_code(&self) -> u8 {
        match self {
            CliError::Generic(_) => 1,
            _ => 2,
        }
    }

    pub fn render(&self, _bin: &str) -> String {
        match self {
            CliError::UnrecognizedSubcommand { command, parent_usage } => {
                format!(
                    "error: unrecognized subcommand '{}'\n\nUsage: {}\n\nFor more information, try '--help'.",
                    command, parent_usage
                )
            }
            CliError::UnexpectedArgument { arg, usage, tip_as_value } => {
                if *tip_as_value {
                    format!(
                        "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: {}\n\nFor more information, try '--help'.",
                        arg, arg, arg, usage
                    )
                } else {
                    format!(
                        "error: unexpected argument '{}' found\n\nUsage: {}\n\nFor more information, try '--help'.",
                        arg, usage
                    )
                }
            }
            CliError::MissingRequired { missing, usage } => {
                let mut s = String::from("error: the following required arguments were not provided:\n");
                for m in missing {
                    s.push_str(&format!("  {}\n", m));
                }
                s.push_str(&format!("\nUsage: {}\n\nFor more information, try '--help'.", usage));
                s
            }
            CliError::ValueRequired { arg } => {
                format!(
                    "error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.",
                    arg
                )
            }
            CliError::InvalidValue { arg, value, reason } => {
                format!(
                    "error: invalid value '{}' for '{}': {}\n\nFor more information, try '--help'.",
                    value, arg, reason
                )
            }
            CliError::RequiresSubcommand { bin, subcommands, usage } => {
                format!(
                    "error: '{}' requires a subcommand but one was not provided\n  [subcommands: {}]\n\nUsage: {}\n\nFor more information, try '--help'.",
                    bin,
                    subcommands.join(", "),
                    usage
                )
            }
            CliError::Generic(s) => s.clone(),
        }
    }
}

impl fmt::Display for CliError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.render("executable"))
    }
}

impl std::error::Error for CliError {}
