//! Shell completion scripts.

macro_rules! embed {
    ($path:literal) => {
        include_str!(concat!("assets/completions/", $path))
    };
}

pub const BASH: &str = embed!("completions_bash.sh");
pub const ZSH: &str = embed!("completions_zsh.sh");
pub const FISH: &str = embed!("completions_fish.sh");
pub const ELVISH: &str = embed!("completions_elvish.sh");
pub const POWERSHELL: &str = embed!("completions_powershell.ps1");

pub fn render_bash(bin: &str) -> String {
    render(BASH, bin, "bash")
}
pub fn render_zsh(bin: &str) -> String {
    render(ZSH, bin, "zsh")
}
pub fn render_fish(bin: &str) -> String {
    render(FISH, bin, "fish")
}
pub fn render_elvish(bin: &str) -> String {
    render(ELVISH, bin, "elvish")
