fn lsp_cmd(bin: &str, args: &[String], _cfg: Option<&str>) -> Result<u8, CliError> {
    // Minimal: only help supported. For actual LSP we emit an error.
    for a in args {
        if a == "--help" {
            print!("{}", ht::render(ht::LSP_HELP, bin));
            return Ok(0);
        }
        if a == "-h" {
            print!("{}", ht::render(ht::LSP_SHORT, bin));
            return Ok(0);
        }
        if a == "-c" || a == "--config" {
            continue;
        }
    }
    // No actual LSP implementation; print the "no project" style error.
