fn completions_cmd(bin: &str, args: &[String], _cfg: Option<&str>) -> Result<u8, CliError> {
    let mut shell: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "--help" => {
                print!("{}", ht::render(ht::COMPLETIONS_HELP, bin));
                return Ok(0);
            }
            "-h" => {
                print!("{}", ht::render(ht::COMPLETIONS_SHORT, bin));
                return Ok(0);
            }
            "-c" | "--config" => {
                i += 2;
                continue;
            }
            s if s.starts_with("--config=") => {
                i += 1;
                continue;
            }
            s if s.starts_with('-') => {
                return Err(CliError::UnexpectedArgument {
                    arg: a.clone(),
                    usage: format!("{} completions [OPTIONS] [SHELL]", bin),
                    tip_as_value: true,
                });
            }
            _ => {
                if shell.is_some() {
                    return Err(CliError::UnexpectedArgument {
                        arg: a.clone(),
                        usage: format!("{} completions [OPTIONS] [SHELL]", bin),
                        tip_as_value: true,
                    });
                }
                shell = Some(a.clone());
            }
        }
        i += 1;
    }

    // Infer shell from env when not provided.
    let shell = match shell {
        Some(s) => s,
        None => {
            if let Ok(s) = std::env::var("SHELL") {
                if let Some(name) = std::path::Path::new(&s)
                    .file_name()
                    .and_then(|f| f.to_str())
                {
                    name.to_string()
                } else {
                    "bash".into()
                }
            } else {
                "bash".into()
            }
        }
    };

    let text = match shell.as_str() {
        "bash" => completions::render_bash(bin),
        "zsh" => completions::render_zsh(bin),
        "fish" => completions::render_fish(bin),
        "elvish" => completions::render_elvish(bin),
        "powershell" => completions::render_powershell(bin),
        other => {
            return Err(CliError::InvalidValue {
                arg: "[SHELL]".into(),
                value: other.into(),
                reason: format!(
                    "possible values: bash, elvish, fish, powershell, zsh"
                ),
            });
        }
    };
    let stdout = io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(text.as_bytes());
    Ok(0)
}

// Validate a language name. Returns true if recognized by ast-grep. The list
// is derived from `ast-grep` documentation (schemas/languages.json).
fn is_known_language(s: &str) -> bool {
    let s = s.to_ascii_lowercase();
    matches!(
        s.as_str(),
        "bash" | "sh"
        | "c"
        | "cpp" | "cc" | "c++"
        | "csharp" | "cs" | "c#"
        | "css"
        | "dart"
        | "elixir" | "ex" | "exs"
        | "go" | "golang"
        | "haskell" | "hs"
        | "html"
        | "java"
        | "javascript" | "js" | "jsx"
        | "json"
        | "kotlin" | "kt" | "kts"
        | "lua"
        | "php"
        | "python" | "py" | "py3"
        | "ruby" | "rb"
        | "rust" | "rs"
        | "scala"
        | "swift"
        | "tsx"
        | "typescript" | "ts"
        | "yaml" | "yml"
    )
}

fn run_cmd(bin: &str, args: &[String], _cfg: Option<&str>) -> Result<u8, CliError> {
