fn completions_cmd(bin: &str, args: &[String], _cfg: Option<&str>) -> Result<u8, CliError> {
    let mut shell: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "--help" => {
                print!("{}", ht::render(ht::COMPLETIONS_HELP, bin));
                return Ok(0);
            }
            "-h" => {
                print!("{}", ht::render(ht::COMPLETIONS_SHORT, bin));
                return Ok(0);
            }
            "-c" | "--config" => {
                i += 2;
                continue;
            }
            s if s.starts_with("--config=") => {
                i += 1;
                continue;
            }
            s if s.starts_with('-') => {
                return Err(CliError::UnexpectedArgument {
                    arg: a.clone(),
                    usage: format!("{} completions [OPTIONS] [SHELL]", bin),
                    tip_as_value: true,
                });
            }
            _ => {
                if shell.is_some() {
                    return Err(CliError::UnexpectedArgument {
                        arg: a.clone(),
                        usage: format!("{} completions [OPTIONS] [SHELL]", bin),
                        tip_as_value: true,
                    });
                }
                shell = Some(a.clone());
            }
        }
        i += 1;
    }

    // Infer shell from env when not provided.
    let shell = match shell {
        Some(s) => s,
        None => {
            if let Ok(s) = std::env::var("SHELL") {
                if let Some(name) = std::path::Path::new(&s)
                    .file_name()
                    .and_then(|f| f.to_str())
                {
                    name.to_string()
                } else {
                    "bash".into()
                }
            } else {
                "bash".into()
            }
        }
    };

    let text = match shell.as_str() {
        "bash" => completions::render_bash(bin),
        "zsh" => completions::render_zsh(bin),
        "fish" => completions::render_fish(bin),
        "elvish" => completions::render_elvish(bin),
        "powershell" => completions::render_powershell(bin),
        other => {
            return Err(CliError::InvalidValue {
                arg: "[SHELL]".into(),
                value: other.into(),
                reason: format!(
                    "possible values: bash, elvish, fish, powershell, zsh"
                ),
            });
        }
    };
    let stdout = io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(text.as_bytes());
    Ok(0)
}

// Validate a language name. Returns true if recognized by ast-grep. The list
// is derived from `ast-grep` documentation (schemas/languages.json).
fn is_known_language(s: &str) -> bool {
    let s = s.to_ascii_lowercase();
    matches!(
        s.as_str(),
        "bash" | "sh"
        | "c"
        | "cpp" | "cc" | "c++"
        | "csharp" | "cs" | "c#"
        | "css"
        | "dart"
        | "elixir" | "ex" | "exs"
        | "go" | "golang"
        | "haskell" | "hs"
        | "html"
        | "java"
        | "javascript" | "js" | "jsx"
        | "json"
        | "kotlin" | "kt" | "kts"
        | "lua"
        | "php"
        | "python" | "py" | "py3"
        | "ruby" | "rb"
        | "rust" | "rs"
        | "scala"
        | "swift"
        | "tsx"
        | "typescript" | "ts"
        | "yaml" | "yml"
    )
}

fn run_cmd(bin: &str, args: &[String], _cfg: Option<&str>) -> Result<u8, CliError> {
    let usage_required = format!(
        "{} run --pattern <PATTERN> [PATHS]...",
        bin
    );
    let mut pattern: Option<String> = None;
    let mut lang: Option<String> = None;
    let mut paths: Vec<String> = Vec::new();
    let mut stdin = false;
    let mut files_with_matches = false;
    let mut i = 0;
    let mut after_ddash = false;
    while i < args.len() {
        let a = &args[i];
        if after_ddash {
            paths.push(a.clone());
            i += 1;
            continue;
        }
        match a.as_str() {
            "--" => after_ddash = true,
            "--help" => {
                print!("{}", ht::render(ht::RUN_HELP, bin));
                return Ok(0);
            }
            "-h" => {
                print!("{}", ht::render(ht::RUN_SHORT, bin));
                return Ok(0);
            }
            "-p" | "--pattern" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: "--pattern <PATTERN>".into(),
                    });
                }
                pattern = Some(args[i].clone());
            }
            s if s.starts_with("--pattern=") => {
                pattern = Some(s["--pattern=".len()..].to_string());
            }
            "-l" | "--lang" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: "--lang <LANG>".into(),
                    });
                }
                let v = args[i].clone();
                if !is_known_language(&v) {
                    return Err(CliError::InvalidValue {
                        arg: "--lang <LANG>".into(),
                        value: v.clone(),
                        reason: format!("{} is not supported!", v),
                    });
                }
                lang = Some(v);
            }
            s if s.starts_with("--lang=") => {
                let v = &s["--lang=".len()..];
                if !is_known_language(v) {
                    return Err(CliError::InvalidValue {
                        arg: "--lang <LANG>".into(),
                        value: v.to_string(),
                        reason: format!("{} is not supported!", v),
                    });
                }
                lang = Some(v.to_string());
            }
            "-r" | "--rewrite" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: "--rewrite <FIX>".into(),
                    });
                }
            }
            s if s.starts_with("--rewrite=") => {}
            "--stdin" => stdin = true,
            "--files-with-matches" => {
                files_with_matches = true;
            }
            "-U" | "--update-all" => {}
            "--follow" => {}
            "-i" | "--interactive" => {}
            "-A" | "--after" | "-B" | "--before" | "-C" | "--context" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: format!("{} <NUM>", a),
                    });
                }
            }
            "-j" | "--threads" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: "--threads <NUM>".into(),
                    });
                }
            }
            "--color" | "--heading" | "--inspect" | "--no-ignore" | "--globs"
            | "--selector" | "--strictness" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: format!("{} <VALUE>", a),
                    });
                }
            }
            s if s.starts_with("--debug-query") => {}
            s if s.starts_with("--json") => {}
            s if s.starts_with('-') => {
                return Err(CliError::UnexpectedArgument {
                    arg: a.clone(),
                    usage: format!("{} run [OPTIONS] --pattern <PATTERN> [PATHS]...", bin),
                    tip_as_value: true,
                });
            }
            _ => paths.push(a.clone()),
        }
        i += 1;
    }

    let _ = (stdin, files_with_matches, &paths);

    let pattern = match pattern {
        Some(p) => p,
        None => {
            return Err(CliError::MissingRequired {
                missing: vec!["--pattern <PATTERN>".into()],
                usage: usage_required,
            });
        }
    };
    let _ = lang; // unused for the minimal implementation

    // Try to read code and pretend to search. The minimal implementation only
    // supports `--stdin` substring search; actual ast-grep pattern matching is
    // not implemented.
    if stdin {
        let mut input = String::new();
        let _ = io::stdin().read_to_string(&mut input);
        let _ = &input;
        let _ = pattern;
    }
    Ok(1)
}

