fn new_cmd(bin: &str, args: &[String], _cfg: Option<&str>) -> Result<u8, CliError> {
    let mut i = 0;
    let mut positionals: Vec<String> = Vec::new();
    let mut show_subhelp: Option<&'static str> = None;
    let mut saw_short = false;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "--help" => {
                // if there is already a positional, show its help; else new help
                if let Some(sub) = positionals.first() {
                    match sub.as_str() {
                        "project" => {
                            print!("{}", ht::render(ht::NEW_PROJECT_HELP, bin));
                            return Ok(0);
                        }
                        "rule" => {
                            print!("{}", ht::render(ht::NEW_RULE_HELP, bin));
                            return Ok(0);
                        }
                        "test" => {
                            print!("{}", ht::render(ht::NEW_TEST_HELP, bin));
                            return Ok(0);
                        }
                        "util" => {
                            print!("{}", ht::render(ht::NEW_UTIL_HELP, bin));
                            return Ok(0);
                        }
                        _ => {}
                    }
                }
                show_subhelp = Some("long");
                break;
            }
            "-h" => {
                if let Some(sub) = positionals.first() {
                    match sub.as_str() {
                        "project" => {
                            print!("{}", ht::render(ht::NEW_PROJECT_SHORT, bin));
                            return Ok(0);
                        }
                        "rule" => {
                            print!("{}", ht::render(ht::NEW_RULE_SHORT, bin));
                            return Ok(0);
                        }
                        "test" => {
                            print!("{}", ht::render(ht::NEW_TEST_SHORT, bin));
                            return Ok(0);
                        }
                        "util" => {
                            print!("{}", ht::render(ht::NEW_UTIL_SHORT, bin));
                            return Ok(0);
                        }
                        _ => {}
                    }
                }
                saw_short = true;
                break;
            }
            _ => positionals.push(a.clone()),
        }
        i += 1;
    }
    let _ = saw_short;
    if show_subhelp.is_some() {
        print!("{}", ht::render(ht::NEW_HELP, bin));
        return Ok(0);
    }
    if saw_short {
        print!("{}", ht::render(ht::NEW_SHORT, bin));
        return Ok(0);
    }
    // No interactive TTY: emulate the no-TTY behavior.
    let first = positionals.first().map(|s| s.as_str()).unwrap_or("");
    if first == "project" {
        println!("Creating a new ast-grep project...");
    } else {
        println!("No sgconfig.yml found. Creating a new ast-grep project...");
    }
    eprintln!("Error: The input device is not a TTY");
    Ok(1)
}
