fn create_project(root: &std::path::Path, _name: Option<&str>) -> Result<(), CliError> {
    let root_display = root.display();
    let rules = root.join("rules");
    let tests = root.join("rule-tests");
    let utils = root.join("utils");
    let _ = std::fs::create_dir_all(&rules);
    let _ = std::fs::create_dir_all(&tests);
    let _ = std::fs::create_dir_all(&utils);
    // .gitkeep in each
    for d in [&rules, &tests, &utils] {
        let _ = std::fs::write(d.join(".gitkeep"), "");
    }
    let sgconfig = format!(
        "ruleDirs:\\n- {}/rules\\ntestConfigs:\\n- testDir: {}/rule-tests\\nutilDirs:\\n- {}/utils\\n",
        root_display, root_display, root_display,
    );
    // The previous format string used \\n literally; use real newlines:
    let sgconfig = format!(
        "ruleDirs:\n- {root}/rules\ntestConfigs:\n- testDir: {root}/rule-tests\nutilDirs:\n- {root}/utils\n",
        root = root_display,
    );
    let _ = std::fs::write(root.join("sgconfig.yml"), sgconfig);
    Ok(())
}

fn create_rule_and_test(name: &str, lang: &str) -> Result<(), CliError> {
    // Determine rule_dir & test_dir from sgconfig.yml (very simplified)
    let conf = std::fs::read_to_string("sgconfig.yml").unwrap_or_default();
    let (rule_dir, test_dir) = parse_sgconfig_dirs(&conf);
    // Canonicalize lang into human form (e.g. "python" -> "Python").
    let lang_name = canonical_language(lang);

    let rule_path = std::path::PathBuf::from(&rule_dir).join(format!("{}.yml", name));
    let rule_content = format!(
        "# yaml-language-server: $schema=https://raw.githubusercontent.com/ast-grep/ast-grep/main/schemas/rule.json\n\nid: {}\nmessage: Add your rule message here....\nseverity: error # error, warning, info, hint\nlanguage: {}\nrule:\n  pattern: Your Rule Pattern here...\n# utils: Extract repeated rule as local utility here.\n# note: Add detailed explanation for the rule.",
        name, lang_name,
    );
    let _ = std::fs::create_dir_all(&rule_dir);
    let _ = std::fs::write(&rule_path, rule_content);
    println!("Created rules at {}", rule_path.display());

    let test_path = std::path::PathBuf::from(&test_dir).join(format!("{}-test.yml", name));
    let test_content = format!(
        "id: {}\nvalid:\n- \"valid code\"\ninvalid:\n- \"invalid code\"\n",
        name,
    );
    let _ = std::fs::create_dir_all(&test_dir);
    let _ = std::fs::write(&test_path, test_content);
    println!("Created test at {}", test_path.display());

    Ok(())
}

fn parse_sgconfig_dirs(conf: &str) -> (String, String) {
    // Extremely naive YAML parser for expected schema
    let mut rule_dir = String::from("rules");
    let mut test_dir = String::from("rule-tests");
    let mut in_rule = false;
    let mut in_test = false;
    for line in conf.lines() {
        let l = line.trim_end();
        if l.starts_with("ruleDirs:") {
            in_rule = true;
            in_test = false;
            continue;
        }
        if l.starts_with("testConfigs:") {
            in_rule = false;
            in_test = true;
            continue;
        }
        if l.starts_with("utilDirs:") {
            in_rule = false;
            in_test = false;
            continue;
        }
        if in_rule {
            if let Some(rest) = l.strip_prefix("- ") {
                rule_dir = rest.to_string();
                in_rule = false;
            }
        } else if in_test {
            if let Some(rest) = l.strip_prefix("- testDir: ") {
                test_dir = rest.to_string();
                in_test = false;
            }
        }
    }
    (rule_dir, test_dir)
}

