    for line in conf.lines() {
        let l = line.trim_end();
        if l.starts_with("ruleDirs:") {
            in_rule = true;
            in_test = false;
            continue;
        }
        if l.starts_with("testConfigs:") {
            in_rule = false;
            in_test = true;
            continue;
        }
        if l.starts_with("utilDirs:") {
            in_rule = false;
            in_test = false;
            continue;
