//! CLI argument parsing and dispatch.
//!
//! Implements a subset of ast-grep's command-line interface. We focus on
//! getting the CLI surface right (help, version, error messages, exit codes).

use std::io::{self, Write};

use crate::completions;
use crate::error::CliError;
use crate::help_text as ht;

pub const VERSION: &str = "ast-grep 0.42.1";

pub fn run(bin: &str, args: &[String]) -> Result<u8, CliError> {
    // Handle top-level `--version`/`-V`.
    for a in args {
        if a == "--" {
            break;
        }
        if a == "--version" || a == "-V" {
            println!("{}", VERSION);
            return Ok(0);
        }
    }

    // Separate global options from the subcommand.
    let mut i = 0;
    let mut config: Option<String> = None;
    while i < args.len() {
        let a = &args[i];
        if a == "--" {
            i += 1;
            break;
        }
        if a == "--help" {
            print!("{}", ht::render(ht::MAIN_HELP, bin));
            return Ok(0);
        }
        if a == "-h" {
            print!("{}", ht::render(ht::MAIN_SHORT, bin));
            return Ok(0);
        }
        if a == "-c" || a == "--config" {
            i += 1;
            if i >= args.len() {
                return Err(CliError::ValueRequired {
                    arg: "--config <CONFIG_FILE>".into(),
                });
            }
            config = Some(args[i].clone());
            i += 1;
            continue;
        }
        if let Some(rest) = a.strip_prefix("--config=") {
            config = Some(rest.to_string());
            i += 1;
            continue;
        }
        break;
    }
    let rest = &args[i..];

    if rest.is_empty() {
        if args.is_empty() {
            print!("{}", ht::render(ht::MAIN_SHORT, bin));
            return Ok(2);
        }
        return Err(CliError::RequiresSubcommand {
            bin: bin.to_string(),
            subcommands: vec!["run", "scan", "test", "new", "lsp", "completions", "help"],
            usage: format!("{} [OPTIONS] <COMMAND>", bin),
        });
    }

    let cmd = &rest[0];
    let rest_args = &rest[1..];
    match cmd.as_str() {
        "run" => run_cmd(bin, rest_args, config.as_deref()),
        "scan" => scan_cmd(bin, rest_args, config.as_deref()),
        "test" => test_cmd(bin, rest_args, config.as_deref()),
        "new" => new_cmd(bin, rest_args, config.as_deref()),
        "lsp" => lsp_cmd(bin, rest_args, config.as_deref()),
        "completions" => completions_cmd(bin, rest_args, config.as_deref()),
        "help" => help_cmd(bin, rest_args),
        _ if cmd.starts_with('-') => run_cmd(bin, rest, config.as_deref()),
        _ => Err(CliError::UnrecognizedSubcommand {
            command: cmd.clone(),
            parent_usage: format!("{} [OPTIONS] <COMMAND>", bin),
        }),
    }
}

fn help_cmd(bin: &str, rest: &[String]) -> Result<u8, CliError> {
    if rest.is_empty() {
        print!("{}", ht::render(ht::MAIN_HELP, bin));
        return Ok(0);
    }
    match rest[0].as_str() {
        "run" => {
            print!("{}", ht::render(ht::RUN_HELP, bin));
            Ok(0)
        }
        "scan" => {
            print!("{}", ht::render(ht::SCAN_HELP, bin));
            Ok(0)
        }
        "test" => {
            print!("{}", ht::render(ht::TEST_HELP, bin));
            Ok(0)
        }
        "new" => {
            if let Some(sub) = rest.get(1) {
                print_new_help(bin, sub, false)
            } else {
                print!("{}", ht::render(ht::NEW_HELP, bin));
                Ok(0)
            }
        }
        "lsp" => {
            print!("{}", ht::render(ht::LSP_HELP, bin));
            Ok(0)
        }
        "completions" => {
            print!("{}", ht::render(ht::COMPLETIONS_HELP, bin));
            Ok(0)
        }
        "help" => {
            print!("{}", ht::render(ht::MAIN_HELP, bin));
            Ok(0)
        }
        other => Err(CliError::UnrecognizedSubcommand {
            command: other.to_string(),
            parent_usage: format!("{} [OPTIONS] <COMMAND>", bin),
        }),
    }
}

