        | "json"
        | "kotlin" | "kt" | "kts"
        | "lua"
        | "php"
        | "python" | "py" | "py3"
        | "ruby" | "rb"
        | "rust" | "rs"
        | "scala"
        | "swift"
        | "tsx"
