        | "yaml" | "yml"
    )
}

fn run_cmd(bin: &str, args: &[String], _cfg: Option<&str>) -> Result<u8, CliError> {
    let usage_required = format!("{} run --pattern <PATTERN> [PATHS]...", bin);
    let mut pattern: Option<String> = None;
    let mut lang: Option<String> = None;
    let mut paths: Vec<String> = Vec::new();
    let mut i = 0;
    let mut after_ddash = false;
    while i < args.len() {
        let a = &args[i];
        if after_ddash {
            paths.push(a.clone());
            i += 1;
            continue;
        }
        match a.as_str() {
            "--" => after_ddash = true,
            "--help" => {
                print!("{}", ht::render(ht::RUN_HELP, bin));
                return Ok(0);
            }
            "-h" => {
                print!("{}", ht::render(ht::RUN_SHORT, bin));
                return Ok(0);
            }
            "-p" | "--pattern" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: "--pattern <PATTERN>".into(),
                    });
                }
                pattern = Some(args[i].clone());
            }
            s if s.starts_with("--pattern=") => {
                pattern = Some(s["--pattern=".len()..].to_string());
            }
            "-l" | "--lang" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: "--lang <LANG>".into(),
                    });
                }
                let v = args[i].clone();
                if !is_known_language(&v) {
                    return Err(CliError::InvalidValue {
                        arg: "--lang <LANG>".into(),
                        value: v.clone(),
                        reason: format!("{} is not supported!", v),
                    });
                }
                lang = Some(v);
            }
            s if s.starts_with("--lang=") => {
                let v = &s["--lang=".len()..];
                if !is_known_language(v) {
                    return Err(CliError::InvalidValue {
                        arg: "--lang <LANG>".into(),
                        value: v.to_string(),
                        reason: format!("{} is not supported!", v),
                    });
                }
                lang = Some(v.to_string());
            }
            "-r" | "--rewrite" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: "--rewrite <FIX>".into(),
                    });
                }
            }
            s if s.starts_with("--rewrite=") => {}
            "--stdin" | "-U" | "--update-all" | "--follow" | "-i" | "--interactive"
            | "--files-with-matches" => {}
            "-A" | "--after" | "-B" | "--before" | "-C" | "--context" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: format!("{} <NUM>", a),
                    });
                }
            }
            "-j" | "--threads" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: "--threads <NUM>".into(),
                    });
                }
            }
            "--color" | "--heading" | "--inspect" | "--no-ignore" | "--globs"
            | "--selector" | "--strictness" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: format!("{} <VALUE>", a),
                    });
                }
            }
            s if s.starts_with("--debug-query") => {}
            s if s.starts_with("--json") => {}
            s if s.starts_with('-') => {
                return Err(CliError::UnexpectedArgument {
                    arg: a.clone(),
                    usage: format!("{} run [OPTIONS] --pattern <PATTERN> [PATHS]...", bin),
                    tip_as_value: true,
                });
            }
            _ => paths.push(a.clone()),
        }
        i += 1;
    }

    let _ = (&paths, &lang);
    if pattern.is_none() {
        return Err(CliError::MissingRequired {
            missing: vec!["--pattern <PATTERN>".into()],
            usage: usage_required,
        });
    }
    Ok(1)
}

