            }
            "-h" => {
                let kind = classify_new_kind(&positionals);
                return print_new_help(bin, kind, true);
            }
            "-y" | "--yes" => yes = true,
            "-l" | "--lang" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: "--lang <LANG>".into(),
                    });
                }
                lang = Some(args[i].clone());
            }
            s if s.starts_with("--lang=") => {
                lang = Some(s["--lang=".len()..].to_string());
            }
            "-c" | "--config" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: "--config <CONFIG_FILE>".into(),
                    });
                }
                _sub_config = Some(args[i].clone());
            }
            s if s.starts_with("--config=") => {
                _sub_config = Some(s["--config=".len()..].to_string());
            }
            _ => positionals.push(a.clone()),
        }
        i += 1;
    }

    // Handle `new help [subcommand]`.
    if positionals.first().map(|s| s.as_str()) == Some("help") {
        let sub = positionals.get(1).map(|s| s.as_str()).unwrap_or("");
        return print_new_help(bin, sub, false);
    }

    let first = positionals.first().map(|s| s.as_str()).unwrap_or("");
    let is_item = matches!(first, "project" | "rule" | "test" | "util");
    let has_config = std::path::Path::new("sgconfig.yml").exists();

    if first == "project" || (!is_item && !has_config) {
        if first == "project" {
            println!("Creating a new ast-grep project...");
        } else {
            println!("No sgconfig.yml found. Creating a new ast-grep project...");
        }
        if !yes {
            eprintln!("Error: The input device is not a TTY");
            return Ok(1);
        }
        let cwd = std::env::current_dir().unwrap_or_default();
        create_project(&cwd)?;
        println!("Your new ast-grep project has been created!");
        return Ok(0);
    }

    if !has_config {
        eprintln!("Error: No ast-grep project configuration is found.");
        eprintln!("Help: You need to create an ast-grep project for this command. Try `sg new` to create one.");
        eprintln!("See also: https://ast-grep.github.io/guide/scan-project.html");
        eprintln!();
        return Ok(3);
    }

    let item_name = positionals.get(1).cloned();
    match first {
        "rule" => {
            if !yes {
                eprintln!("Error: The input device is not a TTY");
                return Ok(1);
            }
            let name = match item_name {
                Some(n) => n,
                None => {
                    eprintln!("Error: Insufficient command line argument provided to use `--yes` option.");
                    eprintln!("Help: You need to provide `name` in command line to use non-interactive `new`.");
                    eprintln!();
                    return Ok(22);
                }
            };
            let lang = match lang {
                Some(l) => l,
                None => {
                    eprintln!("Error: Insufficient command line argument provided to use `--yes` option.");
                    eprintln!("Help: You need to provide `lang` in command line to use non-interactive `new`.");
                    eprintln!();
                    return Ok(22);
                }
            };
            create_rule_and_test(&name, &lang)?;
            Ok(0)
        }
        _ => {
            eprintln!("Error: The input device is not a TTY");
            Ok(1)
        }
    }
}

fn classify_new_kind(pos: &[String]) -> &'static str {
    match pos.first().map(|s| s.as_str()) {
        Some("project") => "project",
        Some("rule") => "rule",
        Some("test") => "test",
        Some("util") => "util",
        _ => "",
    }
}

fn print_new_help(bin: &str, kind: &str, short: bool) -> Result<u8, CliError> {
    let t = match kind {
        "project" => if short { ht::NEW_PROJECT_SHORT } else { ht::NEW_PROJECT_HELP },
        "rule" => if short { ht::NEW_RULE_SHORT } else { ht::NEW_RULE_HELP },
        "test" => if short { ht::NEW_TEST_SHORT } else { ht::NEW_TEST_HELP },
        "util" => if short { ht::NEW_UTIL_SHORT } else { ht::NEW_UTIL_HELP },
        _ => if short { ht::NEW_SHORT } else { ht::NEW_HELP },
    };
    print!("{}", ht::render(t, bin));
    Ok(0)
}

fn create_project(root: &std::path::Path) -> Result<(), CliError> {
    let rules = root.join("rules");
    let tests = root.join("rule-tests");
    let utils = root.join("utils");
    let _ = std::fs::create_dir_all(&rules);
    let _ = std::fs::create_dir_all(&tests);
    let _ = std::fs::create_dir_all(&utils);
    for d in [&rules, &tests, &utils] {
        let _ = std::fs::write(d.join(".gitkeep"), "");
    }
    let sgconfig = format!(
        "ruleDirs:\n- {root}/rules\ntestConfigs:\n- testDir: {root}/rule-tests\nutilDirs:\n- {root}/utils\n",
        root = root.display(),
    );
    let _ = std::fs::write(root.join("sgconfig.yml"), sgconfig);
    Ok(())
}

fn create_rule_and_test(name: &str, lang: &str) -> Result<(), CliError> {
    let conf = std::fs::read_to_string("sgconfig.yml").unwrap_or_default();
    let (rule_dir, test_dir) = parse_sgconfig_dirs(&conf);
    let lang_name = canonical_language(lang);

    let rule_path = std::path::PathBuf::from(&rule_dir).join(format!("{}.yml", name));
    let rule_content = format!(
        "# yaml-language-server: $schema=https://raw.githubusercontent.com/ast-grep/ast-grep/main/schemas/rule.json\n\nid: {id}\nmessage: Add your rule message here....\nseverity: error # error, warning, info, hint\nlanguage: {lang}\nrule:\n  pattern: Your Rule Pattern here...\n# utils: Extract repeated rule as local utility here.\n# note: Add detailed explanation for the rule.",
        id = name, lang = lang_name,
    );
    let _ = std::fs::create_dir_all(&rule_dir);
    let _ = std::fs::write(&rule_path, rule_content);
    println!("Created rules at {}", rule_path.display());

    let test_path = std::path::PathBuf::from(&test_dir).join(format!("{}-test.yml", name));
    let test_content = format!(
        "id: {id}\nvalid:\n- \"valid code\"\ninvalid:\n- \"invalid code\"\n",
        id = name,
    );
    let _ = std::fs::create_dir_all(&test_dir);
    let _ = std::fs::write(&test_path, test_content);
    println!("Created test at {}", test_path.display());

    Ok(())
}

fn parse_sgconfig_dirs(conf: &str) -> (String, String) {
    let mut rule_dir = String::from("rules");
    let mut test_dir = String::from("rule-tests");
    let mut in_rule = false;
    let mut in_test = false;
    for line in conf.lines() {
        let l = line.trim_end();
        if l.starts_with("ruleDirs:") {
            in_rule = true;
            in_test = false;
            continue;
        }
        if l.starts_with("testConfigs:") {
            in_rule = false;
            in_test = true;
            continue;
        }
        if l.starts_with("utilDirs:") {
            in_rule = false;
            in_test = false;
            continue;
        }
        if in_rule {
            if let Some(rest) = l.strip_prefix("- ") {
                rule_dir = rest.to_string();
                in_rule = false;
            }
        } else if in_test {
            if let Some(rest) = l.strip_prefix("- testDir: ") {
                test_dir = rest.to_string();
                in_test = false;
            }
        }
    }
    (rule_dir, test_dir)
}

fn canonical_language(s: &str) -> String {
    match s.to_ascii_lowercase().as_str() {
        "bash" | "sh" => "Bash".into(),
        "c" => "C".into(),
        "cpp" | "cc" | "c++" => "Cpp".into(),
        "csharp" | "cs" | "c#" => "CSharp".into(),
        "css" => "Css".into(),
        "dart" => "Dart".into(),
        "elixir" | "ex" | "exs" => "Elixir".into(),
        "go" | "golang" => "Go".into(),
        "haskell" | "hs" => "Haskell".into(),
        "html" => "Html".into(),
        "java" => "Java".into(),
        "javascript" | "js" | "jsx" => "JavaScript".into(),
        "json" => "Json".into(),
        "kotlin" | "kt" | "kts" => "Kotlin".into(),
        "lua" => "Lua".into(),
        "php" => "Php".into(),
        "python" | "py" | "py3" => "Python".into(),
        "ruby" | "rb" => "Ruby".into(),
        "rust" | "rs" => "Rust".into(),
        "scala" => "Scala".into(),
        "swift" => "Swift".into(),
        "tsx" => "Tsx".into(),
        "typescript" | "ts" => "TypeScript".into(),
        "yaml" | "yml" => "Yaml".into(),
        other => other.to_string(),
    }
}
