//! CLI argument parsing and dispatch.
//!
//! Implements a subset of ast-grep's command-line interface. We focus on
//! getting the CLI surface right (help, version, error messages, exit codes).

use std::io::{self, Write};

use crate::completions;
use crate::error::CliError;
use crate::help_text as ht;

pub const VERSION: &str = "ast-grep 0.42.1";

pub fn run(bin: &str, args: &[String]) -> Result<u8, CliError> {
    // Handle top-level `--version`/`-V`.
    for a in args {
        if a == "--" {
            break;
        }
        if a == "--version" || a == "-V" {
            println!("{}", VERSION);
            return Ok(0);
        }
    }

    // Separate global options from the subcommand.
    let mut i = 0;
    let mut config: Option<String> = None;
    while i < args.len() {
        let a = &args[i];
        if a == "--" {
            i += 1;
            break;
        }
        if a == "--help" {
            print!("{}", ht::render(ht::MAIN_HELP, bin));
            return Ok(0);
        }
        if a == "-h" {
            print!("{}", ht::render(ht::MAIN_SHORT, bin));
            return Ok(0);
        }
        if a == "-c" || a == "--config" {
            i += 1;
            if i >= args.len() {
                return Err(CliError::ValueRequired {
                    arg: "--config <CONFIG_FILE>".into(),
                });
            }
            config = Some(args[i].clone());
            i += 1;
            continue;
        }
        if let Some(rest) = a.strip_prefix("--config=") {
            config = Some(rest.to_string());
            i += 1;
            continue;
        }
        break;
    }
    let rest = &args[i..];

    if rest.is_empty() {
        if args.is_empty() {
            print!("{}", ht::render(ht::MAIN_SHORT, bin));
            return Ok(2);
        }
        return Err(CliError::RequiresSubcommand {
            bin: bin.to_string(),
            subcommands: vec!["run", "scan", "test", "new", "lsp", "completions", "help"],
            usage: format!("{} [OPTIONS] <COMMAND>", bin),
        });
    }

    let cmd = &rest[0];
    let rest_args = &rest[1..];
    match cmd.as_str() {
        "run" => run_cmd(bin, rest_args, config.as_deref()),
        "scan" => scan_cmd(bin, rest_args, config.as_deref()),
        "test" => test_cmd(bin, rest_args, config.as_deref()),
        "new" => new_cmd(bin, rest_args, config.as_deref()),
        "lsp" => lsp_cmd(bin, rest_args, config.as_deref()),
        "completions" => completions_cmd(bin, rest_args, config.as_deref()),
        "help" => help_cmd(bin, rest_args),
        _ if cmd.starts_with('-') => run_cmd(bin, rest, config.as_deref()),
        _ => Err(CliError::UnrecognizedSubcommand {
            command: cmd.clone(),
            parent_usage: format!("{} [OPTIONS] <COMMAND>", bin),
        }),
    }
}

fn help_cmd(bin: &str, rest: &[String]) -> Result<u8, CliError> {
    if rest.is_empty() {
        print!("{}", ht::render(ht::MAIN_HELP, bin));
        return Ok(0);
    }
    match rest[0].as_str() {
        "run" => {
            print!("{}", ht::render(ht::RUN_HELP, bin));
            Ok(0)
        }
        "scan" => {
            print!("{}", ht::render(ht::SCAN_HELP, bin));
            Ok(0)
        }
        "test" => {
            print!("{}", ht::render(ht::TEST_HELP, bin));
            Ok(0)
        }
        "new" => {
            if let Some(sub) = rest.get(1) {
                print_new_help(bin, sub, false)
            } else {
                print!("{}", ht::render(ht::NEW_HELP, bin));
                Ok(0)
            }
        }
        "lsp" => {
            print!("{}", ht::render(ht::LSP_HELP, bin));
            Ok(0)
        }
        "completions" => {
            print!("{}", ht::render(ht::COMPLETIONS_HELP, bin));
            Ok(0)
        }
        "help" => {
            print!("{}", ht::render(ht::MAIN_HELP, bin));
            Ok(0)
        }
        other => Err(CliError::UnrecognizedSubcommand {
            command: other.to_string(),
            parent_usage: format!("{} [OPTIONS] <COMMAND>", bin),
        }),
    }
}

fn lsp_cmd(bin: &str, args: &[String], _cfg: Option<&str>) -> Result<u8, CliError> {
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "--help" => {
                print!("{}", ht::render(ht::LSP_HELP, bin));
                return Ok(0);
            }
            "-h" => {
                print!("{}", ht::render(ht::LSP_SHORT, bin));
                return Ok(0);
            }
            _ => {}
        }
        i += 1;
    }
    eprintln!("Error: No ast-grep project configuration is found.");
    eprintln!("Help: You need to create an ast-grep project for this command. Try `sg new` to create one.");
    eprintln!("See also: https://ast-grep.github.io/guide/scan-project.html");
    eprintln!();
    Ok(0)
}

fn completions_cmd(bin: &str, args: &[String], _cfg: Option<&str>) -> Result<u8, CliError> {
    let mut shell: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "--help" => {
                print!("{}", ht::render(ht::COMPLETIONS_HELP, bin));
                return Ok(0);
            }
            "-h" => {
                print!("{}", ht::render(ht::COMPLETIONS_SHORT, bin));
                return Ok(0);
            }
            "-c" | "--config" => {
                i += 2;
                continue;
            }
            s if s.starts_with("--config=") => {
                i += 1;
                continue;
            }
            s if s.starts_with('-') => {
                return Err(CliError::UnexpectedArgument {
                    arg: a.clone(),
                    usage: format!("{} completions [OPTIONS] [SHELL]", bin),
                    tip_as_value: true,
                });
            }
            _ => {
                if shell.is_some() {
                    return Err(CliError::UnexpectedArgument {
                        arg: a.clone(),
                        usage: format!("{} completions [OPTIONS] [SHELL]", bin),
                        tip_as_value: true,
                    });
                }
                shell = Some(a.clone());
            }
        }
        i += 1;
    }

    let shell = match shell {
        Some(s) => s,
        None => std::env::var("SHELL")
            .ok()
            .and_then(|s| {
                std::path::Path::new(&s)
                    .file_name()
                    .map(|f| f.to_string_lossy().into_owned())
            })
            .unwrap_or_else(|| "bash".into()),
    };

    let text = match shell.as_str() {
        "bash" => completions::render_bash(bin),
        "zsh" => completions::render_zsh(bin),
        "fish" => completions::render_fish(bin),
        "elvish" => completions::render_elvish(bin),
        "powershell" => completions::render_powershell(bin),
        other => {
            return Err(CliError::InvalidValue {
                arg: "[SHELL]".into(),
                value: other.into(),
                reason: "possible values: bash, elvish, fish, powershell, zsh".into(),
            });
        }
    };
    let stdout = io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(text.as_bytes());
    Ok(0)
}

fn is_known_language(s: &str) -> bool {
    let s = s.to_ascii_lowercase();
    matches!(
        s.as_str(),
        "bash" | "sh"
        | "c"
        | "cpp" | "cc" | "c++"
        | "csharp" | "cs" | "c#"
        | "css"
        | "dart"
        | "elixir" | "ex" | "exs"
        | "go" | "golang"
        | "haskell" | "hs"
        | "html"
        | "java"
        | "javascript" | "js" | "jsx"
        | "json"
        | "kotlin" | "kt" | "kts"
        | "lua"
        | "php"
        | "python" | "py" | "py3"
        | "ruby" | "rb"
        | "rust" | "rs"
        | "scala"
        | "swift"
        | "tsx"
        | "typescript" | "ts"
        | "yaml" | "yml"
    )
}

fn run_cmd(bin: &str, args: &[String], _cfg: Option<&str>) -> Result<u8, CliError> {
    let usage_required = format!("{} run --pattern <PATTERN> [PATHS]...", bin);
    let mut pattern: Option<String> = None;
    let mut lang: Option<String> = None;
    let mut paths: Vec<String> = Vec::new();
    let mut i = 0;
    let mut after_ddash = false;
    while i < args.len() {
        let a = &args[i];
        if after_ddash {
            paths.push(a.clone());
            i += 1;
            continue;
        }
        match a.as_str() {
            "--" => after_ddash = true,
            "--help" => {
                print!("{}", ht::render(ht::RUN_HELP, bin));
                return Ok(0);
            }
            "-h" => {
                print!("{}", ht::render(ht::RUN_SHORT, bin));
                return Ok(0);
            }
            "-p" | "--pattern" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: "--pattern <PATTERN>".into(),
                    });
                }
                pattern = Some(args[i].clone());
            }
            s if s.starts_with("--pattern=") => {
                pattern = Some(s["--pattern=".len()..].to_string());
            }
            "-l" | "--lang" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: "--lang <LANG>".into(),
                    });
                }
                let v = args[i].clone();
                if !is_known_language(&v) {
                    return Err(CliError::InvalidValue {
                        arg: "--lang <LANG>".into(),
                        value: v.clone(),
                        reason: format!("{} is not supported!", v),
                    });
                }
                lang = Some(v);
            }
            s if s.starts_with("--lang=") => {
                let v = &s["--lang=".len()..];
                if !is_known_language(v) {
                    return Err(CliError::InvalidValue {
                        arg: "--lang <LANG>".into(),
                        value: v.to_string(),
                        reason: format!("{} is not supported!", v),
                    });
                }
                lang = Some(v.to_string());
            }
            "-r" | "--rewrite" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: "--rewrite <FIX>".into(),
                    });
                }
            }
            s if s.starts_with("--rewrite=") => {}
            "--stdin" | "-U" | "--update-all" | "--follow" | "-i" | "--interactive"
            | "--files-with-matches" => {}
            "-A" | "--after" | "-B" | "--before" | "-C" | "--context" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: format!("{} <NUM>", a),
                    });
                }
            }
            "-j" | "--threads" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: "--threads <NUM>".into(),
                    });
                }
            }
            "--color" | "--heading" | "--inspect" | "--no-ignore" | "--globs"
            | "--selector" | "--strictness" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: format!("{} <VALUE>", a),
                    });
                }
            }
            s if s.starts_with("--debug-query") => {}
            s if s.starts_with("--json") => {}
            s if s.starts_with('-') => {
                return Err(CliError::UnexpectedArgument {
                    arg: a.clone(),
                    usage: format!("{} run [OPTIONS] --pattern <PATTERN> [PATHS]...", bin),
                    tip_as_value: true,
                });
            }
            _ => paths.push(a.clone()),
        }
        i += 1;
    }

    let _ = (&paths, &lang);
    if pattern.is_none() {
        return Err(CliError::MissingRequired {
            missing: vec!["--pattern <PATTERN>".into()],
            usage: usage_required,
        });
    }
    Ok(1)
}

fn scan_cmd(bin: &str, args: &[String], _cfg: Option<&str>) -> Result<u8, CliError> {
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "--help" => {
                print!("{}", ht::render(ht::SCAN_HELP, bin));
                return Ok(0);
            }
            "-h" => {
                print!("{}", ht::render(ht::SCAN_SHORT, bin));
                return Ok(0);
            }
            _ => {}
        }
        i += 1;
    }
    eprintln!("Error: No ast-grep project configuration is found.");
    eprintln!("Help: You need to create an ast-grep project for this command. Try `sg new` to create one.");
    eprintln!("See also: https://ast-grep.github.io/guide/scan-project.html");
    eprintln!();
    Ok(0)
}

fn test_cmd(bin: &str, args: &[String], _cfg: Option<&str>) -> Result<u8, CliError> {
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "--help" => {
                print!("{}", ht::render(ht::TEST_HELP, bin));
                return Ok(0);
            }
            "-h" => {
                print!("{}", ht::render(ht::TEST_SHORT, bin));
                return Ok(0);
            }
            _ => {}
        }
        i += 1;
    }
    eprintln!("Error: No ast-grep project configuration is found.");
    eprintln!("Help: You need to create an ast-grep project for this command. Try `sg new` to create one.");
    eprintln!("See also: https://ast-grep.github.io/guide/scan-project.html");
    eprintln!();
    Ok(0)
}

fn new_cmd(bin: &str, args: &[String], _cfg: Option<&str>) -> Result<u8, CliError> {
    let mut i = 0;
    let mut positionals: Vec<String> = Vec::new();
    let mut yes = false;
    let mut lang: Option<String> = None;
    let mut _sub_config: Option<String> = None;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "--help" => {
                let kind = classify_new_kind(&positionals);
                return print_new_help(bin, kind, false);
            }
            "-h" => {
                let kind = classify_new_kind(&positionals);
                return print_new_help(bin, kind, true);
            }
            "-y" | "--yes" => yes = true,
            "-l" | "--lang" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: "--lang <LANG>".into(),
                    });
                }
                lang = Some(args[i].clone());
            }
            s if s.starts_with("--lang=") => {
                lang = Some(s["--lang=".len()..].to_string());
            }
            "-c" | "--config" => {
                i += 1;
                if i >= args.len() {
                    return Err(CliError::ValueRequired {
                        arg: "--config <CONFIG_FILE>".into(),
                    });
                }
                _sub_config = Some(args[i].clone());
            }
            s if s.starts_with("--config=") => {
                _sub_config = Some(s["--config=".len()..].to_string());
            }
            _ => positionals.push(a.clone()),
        }
        i += 1;
    }

    // Handle `new help [subcommand]`.
    if positionals.first().map(|s| s.as_str()) == Some("help") {
        let sub = positionals.get(1).map(|s| s.as_str()).unwrap_or("");
        return print_new_help(bin, sub, false);
    }

    let first = positionals.first().map(|s| s.as_str()).unwrap_or("");
    let is_item = matches!(first, "project" | "rule" | "test" | "util");
    let has_config = std::path::Path::new("sgconfig.yml").exists();

    if first == "project" || (!is_item && !has_config) {
        if first == "project" {
            println!("Creating a new ast-grep project...");
        } else {
            println!("No sgconfig.yml found. Creating a new ast-grep project...");
        }
        if !yes {
            eprintln!("Error: The input device is not a TTY");
            return Ok(1);
        }
        let cwd = std::env::current_dir().unwrap_or_default();
        create_project(&cwd)?;
        println!("Your new ast-grep project has been created!");
        return Ok(0);
    }

    if !has_config {
        eprintln!("Error: No ast-grep project configuration is found.");
        eprintln!("Help: You need to create an ast-grep project for this command. Try `sg new` to create one.");
        eprintln!("See also: https://ast-grep.github.io/guide/scan-project.html");
        eprintln!();
        return Ok(3);
    }

    let item_name = positionals.get(1).cloned();
    match first {
        "rule" => {
            if !yes {
                eprintln!("Error: The input device is not a TTY");
                return Ok(1);
            }
            let name = match item_name {
                Some(n) => n,
                None => {
                    eprintln!("Error: Insufficient command line argument provided to use `--yes` option.");
                    eprintln!("Help: You need to provide `name` in command line to use non-interactive `new`.");
                    eprintln!();
                    return Ok(22);
                }
            };
            let lang = match lang {
                Some(l) => l,
                None => {
                    eprintln!("Error: Insufficient command line argument provided to use `--yes` option.");
                    eprintln!("Help: You need to provide `lang` in command line to use non-interactive `new`.");
                    eprintln!();
                    return Ok(22);
                }
            };
            create_rule_and_test(&name, &lang)?;
            Ok(0)
        }
        _ => {
            eprintln!("Error: The input device is not a TTY");
            Ok(1)
        }
    }
}

fn classify_new_kind(pos: &[String]) -> &'static str {
    match pos.first().map(|s| s.as_str()) {
        Some("project") => "project",
        Some("rule") => "rule",
        Some("test") => "test",
        Some("util") => "util",
        _ => "",
    }
}

fn print_new_help(bin: &str, kind: &str, short: bool) -> Result<u8, CliError> {
    let t = match kind {
        "project" => if short { ht::NEW_PROJECT_SHORT } else { ht::NEW_PROJECT_HELP },
        "rule" => if short { ht::NEW_RULE_SHORT } else { ht::NEW_RULE_HELP },
        "test" => if short { ht::NEW_TEST_SHORT } else { ht::NEW_TEST_HELP },
        "util" => if short { ht::NEW_UTIL_SHORT } else { ht::NEW_UTIL_HELP },
        _ => if short { ht::NEW_SHORT } else { ht::NEW_HELP },
    };
    print!("{}", ht::render(t, bin));
    Ok(0)
}

fn create_project(root: &std::path::Path) -> Result<(), CliError> {
    let rules = root.join("rules");
    let tests = root.join("rule-tests");
    let utils = root.join("utils");
    let _ = std::fs::create_dir_all(&rules);
    let _ = std::fs::create_dir_all(&tests);
    let _ = std::fs::create_dir_all(&utils);
    for d in [&rules, &tests, &utils] {
        let _ = std::fs::write(d.join(".gitkeep"), "");
    }
    let sgconfig = format!(
        "ruleDirs:\n- {root}/rules\ntestConfigs:\n- testDir: {root}/rule-tests\nutilDirs:\n- {root}/utils\n",
        root = root.display(),
    );
    let _ = std::fs::write(root.join("sgconfig.yml"), sgconfig);
    Ok(())
}

fn create_rule_and_test(name: &str, lang: &str) -> Result<(), CliError> {
    let conf = std::fs::read_to_string("sgconfig.yml").unwrap_or_default();
    let (rule_dir, test_dir) = parse_sgconfig_dirs(&conf);
    let lang_name = canonical_language(lang);

    let rule_path = std::path::PathBuf::from(&rule_dir).join(format!("{}.yml", name));
    let rule_content = format!(
        "# yaml-language-server: $schema=https://raw.githubusercontent.com/ast-grep/ast-grep/main/schemas/rule.json\n\nid: {id}\nmessage: Add your rule message here....\nseverity: error # error, warning, info, hint\nlanguage: {lang}\nrule:\n  pattern: Your Rule Pattern here...\n# utils: Extract repeated rule as local utility here.\n# note: Add detailed explanation for the rule.",
        id = name, lang = lang_name,
    );
    let _ = std::fs::create_dir_all(&rule_dir);
    let _ = std::fs::write(&rule_path, rule_content);
    println!("Created rules at {}", rule_path.display());

    let test_path = std::path::PathBuf::from(&test_dir).join(format!("{}-test.yml", name));
    let test_content = format!(
        "id: {id}\nvalid:\n- \"valid code\"\ninvalid:\n- \"invalid code\"\n",
        id = name,
    );
    let _ = std::fs::create_dir_all(&test_dir);
    let _ = std::fs::write(&test_path, test_content);
    println!("Created test at {}", test_path.display());

    Ok(())
}

fn parse_sgconfig_dirs(conf: &str) -> (String, String) {
    let mut rule_dir = String::from("rules");
    let mut test_dir = String::from("rule-tests");
    let mut in_rule = false;
    let mut in_test = false;
    for line in conf.lines() {
        let l = line.trim_end();
        if l.starts_with("ruleDirs:") {
            in_rule = true;
            in_test = false;
            continue;
        }
        if l.starts_with("testConfigs:") {
            in_rule = false;
            in_test = true;
            continue;
        }
        if l.starts_with("utilDirs:") {
            in_rule = false;
            in_test = false;
            continue;
        }
        if in_rule {
            if let Some(rest) = l.strip_prefix("- ") {
                rule_dir = rest.to_string();
                in_rule = false;
            }
        } else if in_test {
            if let Some(rest) = l.strip_prefix("- testDir: ") {
                test_dir = rest.to_string();
                in_test = false;
            }
        }
    }
    (rule_dir, test_dir)
}

fn canonical_language(s: &str) -> String {
    match s.to_ascii_lowercase().as_str() {
        "bash" | "sh" => "Bash".into(),
        "c" => "C".into(),
        "cpp" | "cc" | "c++" => "Cpp".into(),
        "csharp" | "cs" | "c#" => "CSharp".into(),
        "css" => "Css".into(),
        "dart" => "Dart".into(),
        "elixir" | "ex" | "exs" => "Elixir".into(),
        "go" | "golang" => "Go".into(),
        "haskell" | "hs" => "Haskell".into(),
        "html" => "Html".into(),
        "java" => "Java".into(),
        "javascript" | "js" | "jsx" => "JavaScript".into(),
        "json" => "Json".into(),
        "kotlin" | "kt" | "kts" => "Kotlin".into(),
        "lua" => "Lua".into(),
        "php" => "Php".into(),
        "python" | "py" | "py3" => "Python".into(),
        "ruby" | "rb" => "Ruby".into(),
        "rust" | "rs" => "Rust".into(),
        "scala" => "Scala".into(),
        "swift" => "Swift".into(),
        "tsx" => "Tsx".into(),
        "typescript" | "ts" => "TypeScript".into(),
        "yaml" | "yml" => "Yaml".into(),
        other => other.to_string(),
    }
}
